record.field:
# Available variables:
#  - env: Odoo Environment on which the action is triggered
#  - model: Odoo Model of the record on which the action is triggered; is a void recordset
#  - record: record on which the action is triggered; may be void
#  - records: recordset of all records on which the action is triggered in multi-mode; may be void
#  - time, datetime, dateutil, timezone: useful Python libraries
#  - float_compare: Odoo function to compare floats based on specific precisions
#  - log: log(message, level='info'): logging function to record debug information in ir.logging table
#  - UserError: Warning Exception to use with raise
#  - Command: x2Many commands namespace
# To return an action, assign: action = {...}
for rec in records:
  atama_durumu = 0
  restoran_paket_arasi_mesafe = 0
  restoran_paket_arasi_yon = 0
  if rec.pos_entegrasyon_firmasi != "adisyo":
    rec["siparis_tarihi"] = datetime.datetime.now()
  magaza = rec.magaza
  uygun_slotlar = env['slots.profile'].search(["&","&","&",["active_status","=",True],["magazalar.id","=",rec.magaza.id],["start_date","<=",rec.siparis_tarihi],["end_date",">=",rec.siparis_tarihi]],limit=1)
  log("uygun_slotlar: " + str(uygun_slotlar), level='info')
  if rec.lat != 0 and rec.lng != 0 and rec.magaza.lat != 0 and rec.magaza.lng != 0:
      restoran_paket_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, rec.lat, rec.lng)
      restoran_paket_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng, rec.lat, rec.lng)
      rec["mesafe"] = restoran_paket_arasi_mesafe
      rec["yon"] = restoran_paket_arasi_yon

  for slot in uygun_slotlar:
    slot["kurye"]["kurye_siparis_puani"] = 0

  # SENARYO -1 -------------------------------------------------------
  if atama_durumu == 0:
    for index, slot in enumerate(uygun_slotlar):
      restoran_kurye_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, slot.kurye.lat, slot.kurye.lng)
      restoran_kurye_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng,slot.kurye.lat, slot.kurye.lng)
      log(slot.kurye.name + " Anlık Paket Sayısı: " + str(slot.kurye.anlik_tasinan_paket_sayisi) + " R-K Metresi: " + str(restoran_kurye_arasi_mesafe) + " R-K Yönü: " + str(restoran_kurye_arasi_yon) + " R-P Metresi: " + str(restoran_paket_arasi_mesafe) + " R-P Yönü: " + str(restoran_paket_arasi_yon), level='info')
      if restoran_kurye_arasi_mesafe <= 500:
        if atama_durumu == 0 and slot.kurye.kurye_durumu == "musait":
          if slot.kurye.anlik_tasinan_paket_sayisi < slot.partner_id.kurye_max_paket_sayisi:
            rec["kurye"] = slot.kurye.id
            rec["kurye_telefonu"] = slot.kurye.mobile
            atama_durumu = 1
            log(str(rec.siparis_no) + " - " + str(rec.kurye.name) + " - Algoritma 1 Üzerinden Atanmıştır.", level='info')

  # SENARYO - 2 - 3 -------------------------------------------------------
  if atama_durumu == 0:
    uygun_slotlar = sorted(
        uygun_slotlar,
        key=lambda slot: model.find_distance(magaza.lat, magaza.lng, slot.kurye.lat, slot.kurye.lng),
        reverse=False
    )
    for index, slot in enumerate(uygun_slotlar):
      restoran_kurye_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, slot.kurye.lat, slot.kurye.lng)
      restoran_kurye_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng,slot.kurye.lat, slot.kurye.lng)
      #log(slot.kurye.name + " R-K Metresi: " + str(restoran_kurye_arasi_mesafe) + " R-K Yönü: " + str(restoran_kurye_arasi_yon) + " R-P Metresi: " + str(restoran_paket_arasi_mesafe) + " R-P Yönü: " + str(restoran_paket_arasi_yon), level='info')
      if restoran_kurye_arasi_mesafe <= 500:
        if atama_durumu == 0 and slot.kurye.kurye_durumu == "pakette":
          if slot.kurye.anlik_tasinan_paket_sayisi < slot.partner_id.kurye_max_paket_sayisi:
            rec["kurye"] = slot.kurye.id
            rec["kurye_telefonu"] = slot.kurye.mobile
            atama_durumu = 1
            log(str(rec.siparis_no) + " - " + str(rec.kurye.name) + " - Algoritma 2 Üzerinden Atanmıştır.", level='info')
      if restoran_kurye_arasi_mesafe <= 1000:
        if atama_durumu == 0 and slot.kurye.kurye_durumu == "musait":
          if slot.kurye.anlik_tasinan_paket_sayisi < slot.partner_id.kurye_max_paket_sayisi:
            rec["kurye"] = slot.kurye.id
            rec["kurye_telefonu"] = slot.kurye.mobile
            atama_durumu = 1
            log(str(rec.siparis_no) + " - " + str(rec.kurye.name) + " - Algoritma 3 Üzerinden Atanmıştır.", level='info')

  # SENARYO - 4 -------------------------------------------------------
  if atama_durumu == 0:
    uygun_slotlar = sorted(
        uygun_slotlar,
        key=lambda slot: model.find_distance(magaza.lat, magaza.lng, slot.kurye.lat, slot.kurye.lng),
        reverse=False
    )
    for index, slot in enumerate(uygun_slotlar):
      restoran_kurye_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, slot.kurye.lat, slot.kurye.lng)
      restoran_kurye_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng,slot.kurye.lat, slot.kurye.lng)
      #log(slot.kurye.name + " R-K Metresi: " + str(restoran_kurye_arasi_mesafe) + " R-K Yönü: " + str(restoran_kurye_arasi_yon) + " R-P Metresi: " + str(restoran_paket_arasi_mesafe) + " R-P Yönü: " + str(restoran_paket_arasi_yon), level='info')
      if restoran_kurye_arasi_mesafe <= 99999999999999999:
        if atama_durumu == 0 and slot.kurye.kurye_durumu == "musait":
          if slot.kurye.anlik_tasinan_paket_sayisi < slot.partner_id.kurye_max_paket_sayisi:
            rec["kurye"] = slot.kurye.id
            rec["kurye_telefonu"] = slot.kurye.mobile
            atama_durumu = 1
            log(str(rec.siparis_no) + " - " + str(rec.kurye.name) + " - Algoritma 4 Üzerinden Atanmıştır.", level='info')

  # SENARYO - 5 -------------------------------------------------------


  player_ids = []
  if len(rec.kurye) > 0:
    if slot.kurye.player_id != False:
      player_ids.append(slot.kurye.player_id)
  if len(magaza) > 0:
    if magaza.player_id != False:
      player_ids.append(slot.kurye.player_id)
  if len(player_ids) > 0:
    if atama_durumu == 1:
      message = "Yeni Sipariş Geldi"
      env['notifier.profile'].send_Push_Notification_With_Playerid("Basic zzzzz5OTgtYWQ0Zi00MTZiLThjODMtNjY3Njk5NGY5NmNh", "4333527bf-b24b-4ea4-adaf-d7ba4dd94232", player_ids ,message)
    if atama_durumu == 0:
      message = "Dikkat! Yeni Siparişe Uygun Kurye Bulamadık"
      env['notifier.profile'].send_Push_Notification_With_Playerid("Basic zzzzz5OTgtYWQ0Zi00MTZiLThjODMtNjY3Njk5NGY5NmNh", "4333527bf-b24b-4ea4-adaf-d7ba4dd94232", player_ids ,message)

# Available variables:
#  - env: Odoo Environment on which the action is triggered
#  - model: Odoo Model of the record on which the action is triggered; is a void recordset
#  - record: record on which the action is triggered; may be void
#  - records: recordset of all records on which the action is triggered in multi-mode; may be void
#  - time, datetime, dateutil, timezone: useful Python libraries
#  - float_compare: Odoo function to compare floats based on specific precisions
#  - log: log(message, level='info'): logging function to record debug information in ir.logging table
#  - UserError: Warning Exception to use with raise
#  - Command: x2Many commands namespace
# To return an action, assign: action = {...}
for rec in records:
  slot = env['slots.profile'].search(["&","&","&",["skurye_profile_lines.partner_id.id","=",rec.kurye.id],["magazalar.id","=",rec.magaza.id],["start_date","<=",rec.siparis_tarihi],["end_date",">=",rec.siparis_tarihi]], limit=1)
  if rec.kurye_siparis_durumu == "yonlendirildi":
    player_ids = []
    if rec.kurye.player_id != False:
      player_ids.append(rec.kurye.player_id)
      message = "Sipariş Yönlendirildi"
      env['notifier.profile'].send_Push_Notification_With_Playerid("Basic zzzzz5OTgtYWQ0Zi00MTZiLThjODMtNjY3Njk5NGY5NmNh", "4333527bf-b24b-4ea4-adaf-d7ba4dd94232", player_ids ,message)
  if rec.kurye_siparis_durumu == "onaylandi":
    if len(slot) > 0:
      for kurye_line in slot.skurye_profile_lines:
        if kurye_line.partner_id.id == rec.kurye.id:
          #kurye_line["partner_id"]["anlik_tasinan_paket_sayisi"] = slot.kurye.anlik_tasinan_paket_sayisi + 1
          kurye_line["partner_id"]["toplam_tasinan_paket"] = rec.kurye.toplam_tasinan_paket + 1
  if rec.kurye_siparis_durumu == "siparisi_teslim_aldi":
    rec["siparis_durumu"] = "yola_cikti"
    rec["paket_baslangic_tarihi"] = datetime.datetime.now()
  #if rec.kurye_siparis_durumu == "siparisi_teslim_aldi" and rec.kurye.kurye_durumu != "mesgul":
  #  rec["kurye"]["kurye_durumu"] = "pakette"
  #  rec["kurye"]["anlik_tasinan_paket_sayisi"] = rec.kurye.anlik_tasinan_paket_sayisi + 1
  if rec.kurye_siparis_durumu == "siparisi_teslim_etti":
    rec["siparis_durumu"] = "teslim_edildi"
  if rec.kurye_siparis_durumu == "siparisi_iptal_etti":
    rec["siparis_durumu"] = "iptal_edildi"

  belirli_saat_oncesi = datetime.datetime.now() - datetime.timedelta(hours = 24)
  if len(rec.kurye) > 0:
    kuryenin_sepetinde_tasidigi_siparisler = env['corders.profile'].search(['&','&','&','&',["siparis_tarihi", ">=", belirli_saat_oncesi],["kurye.id","=",rec.kurye.id],["kurye_siparis_durumu","=","siparisi_teslim_aldi"],["siparis_durumu","!=","teslim_edildi"],["siparis_durumu","!=","iptal_edildi"]])
    rec["kurye"]["anlik_tasinan_paket_sayisi"] = len(kuryenin_sepetinde_tasidigi_siparisler)
    if len(kuryenin_sepetinde_tasidigi_siparisler) > 0 and rec.kurye.kurye_durumu != "mesgul":
      rec["kurye"]["kurye_durumu"] = "pakette"
    kuryenin_tum_devam_eden_siparisleri = env['corders.profile'].search(['&','&','&',["siparis_tarihi", ">=", belirli_saat_oncesi],["kurye.id","=",rec.kurye.id],["siparis_durumu","!=","teslim_edildi"],["siparis_durumu","!=","iptal_edildi"]])
    rec["kurye"]["uzerindeki_paket_sayisi"] = len(kuryenin_tum_devam_eden_siparisleri)

# Available variables:
#  - env: Odoo Environment on which the action is triggered
#  - model: Odoo Model of the record on which the action is triggered; is a void recordset
#  - record: record on which the action is triggered; may be void
#  - records: recordset of all records on which the action is triggered in multi-mode; may be void
#  - time, datetime, dateutil, timezone: useful Python libraries
#  - float_compare: Odoo function to compare floats based on specific precisions
#  - log: log(message, level='info'): logging function to record debug information in ir.logging table
#  - UserError: Warning Exception to use with raise
#  - Command: x2Many commands namespace
# To return an action, assign: action = {...}
for rec in records:
  if rec.siparis_no == False and rec.pos_entegrasyon_firmasi == False:
    rec["siparis_no"] = model.generate_random_code()
  if rec.musteri_adi == False and rec.pos_entegrasyon_firmasi == False:
    raise UserError(("Lütfen Müşteri Adını Giriniz!"))
  if rec.adres == False and rec.pos_entegrasyon_firmasi == False:
    raise UserError(("Lütfen Adres Alanını Giriniz!"))
  if rec.odeme_yontemi == False and rec.pos_entegrasyon_firmasi == False:
    raise UserError(("Lütfen Ödeme Yöntemi Alanını Giriniz!"))
  if rec.platform == False and rec.pos_entegrasyon_firmasi == False:
    raise UserError(("Lütfen Platform Alanını Giriniz!"))
  if len(rec.magaza) == 0 and rec.pos_entegrasyon_firmasi == False:
    raise UserError(("Lütfen Mağaza Alanını Giriniz!"))
  if rec.musteri_telefonu == False:
    raise UserError(("Lütfen Müşteri Telefonu Alanını Giriniz!"))
  atama_durumu = 0
  restoran_paket_arasi_mesafe = 0
  restoran_paket_arasi_yon = 0
  restoran_kurye_arasi_mesafe = 0
  restoran_kurye_arasi_yon = 0
  min_degree = 0
  rec["siparis_tarihi"] = datetime.datetime.now()
  magaza = rec.magaza
  lat = 0
  lng = 0
  if rec.lat == 0 and rec.lng == 0 and rec.adres != False:
    response = model.get_lat_lng(rec.id,str(rec.adres) + " " + str(rec.adres_tarifi))
    if response["status"] == "OK":
      if 'geometry' in response["results"][0]:
        if 'location' in response["results"][0]["geometry"]:
          lat = response["results"][0]["geometry"]["location"]["lat"]
          lng = response["results"][0]["geometry"]["location"]["lng"]
          log(str(rec.id) + " id' li Siparişte google maps api ile konum bilgisi alındı.", level='info')
    if lat > 0 and lng > 0:
      rec["lat"] = lat
      rec["lng"] = lng
  assigned_courier = rec.auto_assign_courier()
  if len(assigned_courier) > 0:
    atama_durumu = 1
  if magaza.slot_tipi == 'sabit':
    uygun_slot = env['slots.profile'].search(["&","&","&",["active_status","=",True],["magazalar.id","=",rec.magaza.id],["start_date","<=",rec.siparis_tarihi],["end_date",">=",rec.siparis_tarihi]],limit=1)
    log("uygun slot id: " + str(uygun_slot.id) + " uygun slot adı: " + str(uygun_slot.name), level='info')
    if rec.lat != 0 and rec.lng != 0 and rec.magaza.lat != 0 and rec.magaza.lng != 0:
        restoran_paket_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, rec.lat, rec.lng)
        if restoran_paket_arasi_mesafe >= 6000:
          restoran_paket_arasi_mesafe = 6000
        restoran_paket_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng, rec.lat, rec.lng)
        rec["mesafe"] = restoran_paket_arasi_mesafe
        rec["yon"] = restoran_paket_arasi_yon


    # SENARYO -A1 -------------------------------------------------------
    if atama_durumu == 0:
      aktif_kuryeler = filter(lambda kurye: kurye.active, uygun_slot.skurye_profile_lines)
      sorted_skurye_profile_lines = sorted(aktif_kuryeler, key=lambda kurye: model.find_distance(magaza.lat, magaza.lng, kurye.partner_id.lat, kurye.partner_id.lng))
      for index, kurye_line in enumerate(sorted_skurye_profile_lines):
        if atama_durumu == 1:
          break
        restoran_kurye_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, kurye_line.partner_id.lat, kurye_line.partner_id.lng)
        restoran_kurye_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng, kurye_line.partner_id.lat, kurye_line.partner_id.lng)
        if restoran_kurye_arasi_mesafe <= 500:
          if atama_durumu == 0 and kurye_line.partner_id.kurye_durumu == "musait" and kurye_line.partner_id.kurye_mola_durumu == False:
            if kurye_line.partner_id.anlik_tasinan_paket_sayisi <= 3:
              kuryenin_devam_eden_siparisleri = env['corders.profile'].search(['&','&',["kurye.id","=",kurye_line.partner_id.id],["siparis_durumu","!=","teslim_edildi"],["siparis_durumu","!=","iptal_edildi"]])
              if len(kuryenin_devam_eden_siparisleri) == 0:
                rec["kurye"] = kurye_line.partner_id.id
                rec["kurye_telefonu"] = kurye_line.partner_id.mobile
                kurye_line["slot_paket_sayisi"] += 1
                atama_durumu = 1
                log(str(rec.siparis_no) + " - " + str(kurye_line.partner_id.name) + " - Algoritma A1-S1 Üzerinden Atanmıştır.", level='info')
              if len(kuryenin_devam_eden_siparisleri) > 0 and len(kuryenin_devam_eden_siparisleri) <= 3:
                sorted_kuryenin_devam_eden_siparisleri = sorted(kuryenin_devam_eden_siparisleri,key=lambda siparis: min(abs(float(siparis.yon) - restoran_paket_arasi_yon),360-abs(float(siparis.yon) - restoran_paket_arasi_yon)),reverse=True)
                for kuryenin_devam_eden_siparisi in sorted_kuryenin_devam_eden_siparisleri:
                  min_degree = min(abs(float(kuryenin_devam_eden_siparisi.yon) - restoran_paket_arasi_yon),360-abs(float(kuryenin_devam_eden_siparisi.yon) - restoran_paket_arasi_yon))
                  if min_degree > 50:
                    break
                  if min_degree <= 50:
                    rec["kurye"] = kurye_line.partner_id.id
                    rec["kurye_telefonu"] = kurye_line.partner_id.mobile
                    kurye_line["slot_paket_sayisi"] += 1
                    atama_durumu = 1
                    log(str(rec.siparis_no) + " - " + str(kurye_line.partner_id.name) + " - Algoritma A1-S2 Üzerinden Atanmıştır.", level='info')
                    break


    # SENARYO -A2 -------------------------------------------------------
    if atama_durumu == 0:
      aktif_kuryeler = filter(lambda kurye: kurye.active, uygun_slot.skurye_profile_lines)
      sorted_skurye_profile_lines = sorted(aktif_kuryeler, key=lambda kurye: model.find_distance(magaza.lat, magaza.lng, kurye.partner_id.lat, kurye.partner_id.lng))
      for index, kurye_line in enumerate(sorted_skurye_profile_lines):
        if atama_durumu == 1:
          break
        restoran_kurye_arasi_mesafe = model.find_distance(magaza.lat, magaza.lng, kurye_line.partner_id.lat, kurye_line.partner_id.lng)
        restoran_kurye_arasi_yon = model.yon_tespiti(magaza.lat, magaza.lng, kurye_line.partner_id.lat, kurye_line.partner_id.lng)
        #log(kurye_line.partner_id.name + " - durumu:" + kurye_line.partner_id.kurye_durumu + " mola durumu: " + str(kurye_line.partner_id.kurye_mola_durumu)  + " Anlık Paket Sayısı: " + str(kurye_line.partner_id.anlik_tasinan_paket_sayisi) + " R-K Metresi: " + str(restoran_kurye_arasi_mesafe) + " R-K Yönü: " + str(restoran_kurye_arasi_yon) + " R-P Metresi: " + str(restoran_paket_arasi_mesafe) + " R-P Yönü: " + str(restoran_paket_arasi_yon), level='info')
        if restoran_kurye_arasi_mesafe <= 1200:
          if atama_durumu == 0 and kurye_line.partner_id.kurye_durumu == "musait" and kurye_line.partner_id.kurye_mola_durumu == False:
            if kurye_line.partner_id.anlik_tasinan_paket_sayisi <= 3:
              kuryenin_devam_eden_siparisleri = env['corders.profile'].search(['&','&',["kurye.id","=",kurye_line.partner_id.id],["siparis_durumu","!=","teslim_edildi"],["siparis_durumu","!=","iptal_edildi"]])
              if len(kuryenin_devam_eden_siparisleri) == 0:
                rec["kurye"] = kurye_line.partner_id.id
                rec["kurye_telefonu"] = kurye_line.partner_id.mobile
                kurye_line["slot_paket_sayisi"] += 1
                atama_durumu = 1
                log(str(rec.siparis_no) + " - " + str(kurye_line.partner_id.name) + " - Algoritma A2-S1 Üzerinden Atanmıştır.", level='info')
              if len(kuryenin_devam_eden_siparisleri) > 0 and len(kuryenin_devam_eden_siparisleri) <= 3:
                sorted_kuryenin_devam_eden_siparisleri = sorted(kuryenin_devam_eden_siparisleri,key=lambda siparis: min(abs(float(siparis.yon) - restoran_paket_arasi_yon),360-abs(float(siparis.yon) - restoran_paket_arasi_yon)),reverse=True)
                for kuryenin_devam_eden_siparisi in sorted_kuryenin_devam_eden_siparisleri:
                  min_degree = min(abs(float(kuryenin_devam_eden_siparisi.yon) - restoran_paket_arasi_yon),360-abs(float(kuryenin_devam_eden_siparisi.yon) - restoran_paket_arasi_yon))
                  if min_degree > 50:
                    break
                  if min_degree <= 50:
                    rec["kurye"] = kurye_line.partner_id.id
                    rec["kurye_telefonu"] = kurye_line.partner_id.mobile
                    kurye_line["slot_paket_sayisi"] += 1
                    atama_durumu = 1
                    log(str(rec.siparis_no) + " - " + str(kurye_line.partner_id.name) + " - Algoritma A2-S2 Üzerinden Atanmıştır.", level='info')
                    break


    # SENARYO -A3 -------------------------------------------------------
    if atama_durumu == 0:
      aktif_kuryeler = filter(lambda kurye: kurye.active, uygun_slot.skurye_profile_lines)
      sorted_skurye_profile_lines = sorted(aktif_kuryeler, key=lambda kurye: model.find_distance(magaza.lat, magaza.lng, kurye.partner_id.lat, kurye.partner_id.lng))
      for index, kurye_line in enumerate(sorted_skurye_profile_lines):
