  player_ids = []
  if len(magaza) > 0:
    player_ids.append(rec.magaza.player_id)
    if atama_durumu == 0:
      if len(player_ids) > 0:
        env['notifier.profile'].send_Push_Notification_With_Playerid("Basic NjM3MTRiOWItYzg0Zi00NGE5LThmY2QtMGYwMTIwNDI5NmM0", "796c5def-6915-4219-b2c4-c71de264806f", player_ids ,str(rec.siparis_no) + " nolu siparişinize kurye atanamadı.")  
