#  - Command: x2Many commands namespace
# To return an action, assign: action = {...}
player_ids = []
current_time = datetime.datetime.now() + datetime.timedelta(hours = 3)
midnight_time = current_time.strftime('%H:%M:%S')
if midnight_time >= "05:30:01" and midnight_time <= "05:35:00":
    tum_kuryeler = env['res.partner'].search([["user_role","=","kurye"]])
    for kurye in tum_kuryeler:
      kurye.sudo().write({
        'mola_kalan_sure': kurye.max_mola_suresi,
        'kurye_mola_durumu': False
      })

kuryeler = env['res.partner'].search(['&',["user_role","=","kurye"],["kurye_mola_durumu","=",True]])
for kurye in kuryeler:
  if kurye.mola_kalan_sure >= 1:
    kalan_sure = kurye.mola_kalan_sure - 1
    kurye["mola_kalan_sure"] = kalan_sure
    if kalan_sure == 0:
      kurye.sudo().write({
        'kurye_mola_durumu': False
      })
      log(str(kurye.id) + " id'li " + str(kurye.name) + " adlı kuryenin mola süresi doldu.", level='info')
      if kurye.player_id != False:
          player_ids.append(kurye.player_id)
if len(player_ids) > 0:
  env['notifier.profile'].send_Push_Notification_With_Playerid_V1("Basic NjM3MTRiOWItYzg0Zi00NGE5LThmY2QtMGYwMTIwNDI5NmM0", "796c5def-6915-4219-b2c4-c71de264806f", player_ids ,"Mola Süren Doldu!","Bugünlük Mola Kotanı Kullandın")

